function setupSpreadsheet() {
    // Variable to track the currently selected cell element
    let activeCell = null;

    // Function to handle setting focus and selection
    const handleCellClick = (e) => {
        let cell = e.target;
        if (!cell.closest('td')) return; // Ensure we clicked on a data cell

        // 1. Deselect previous active cell
        if (activeCell) {
            activeCell.classList.remove('selected-cell');
        }

        // 2. Set new active cell and apply selection visual
        activeCell = cell;
        activeCell.classList.add('selected-cell');

        // Optional: Focus the cell for better UX (though contenteditable handles this)
        // cell.focus(); 
    };


    // Function to handle cell input and automatic formula calculation
    const handleInput = (e) => {
        let cell = e.target;
        let value = cell.innerText.trim();

        if (!value) return;

        if (typeof value === 'string' && value.startsWith('=')) {
            // Intercept the input if it looks like a formula
            const formula = value;

            try {
                // Calculate and update the cell content
                const result = evaluateFormula(formula, document); 
                cell.innerText = result;
            } catch (e) {
                 console.error("Error handling input:", e);
            }
        } else if (!value.startsWith('=')) {
             // If user inputs plain text/number, we don't override it.
        }
    };

    const cells = document.querySelectorAll('#spreadsheetTable td[contenteditable="true"]');

    cells.forEach(cell => {
        // Use 'click' event to track selection (primary interaction for this feature)
        cell.addEventListener('click', handleCellClick); 
        // Use 'input' event to catch changes from typing or pasting
        cell.addEventListener('input', handleInput);
    });


    console.log("Spreadsheet App Initialized: Ready for input.");

    // --- Setup Color Controls Listener ---
    const colorPicker = document.getElementById('bgColorPicker');
    const applyButton = document.getElementById('applyColorButton');

    if (colorPicker && applyButton) {
        applyButton.addEventListener('click', () => {
            if (!activeCell) {
                alert("Please select a cell first.");
                return;
            }

            const color = colorPicker.value;
            // Apply the background color directly to the active cell element
            activeCell.style.backgroundColor = color;
        });
    }
}
