function selectCellHandler(e) {
    // Ensure we are clicking on an editable data cell (td).
    const target = e.target;
    if (!target || !target.hasAttribute('data-cell') || !target.getAttribute('contenteditable')) return;

    // 1. Deselect previous cell
    document.querySelectorAll('.selected-cell').forEach(el => {
        el.classList.remove('selected-cell');
    });

    // 2. Select current cell and store reference
    target.classList.add('selected-cell');
}
