function setupSpreadsheet() {
    let selectedCell = null; // Global tracker for the currently active cell

    // Function to handle cell input and automatic formula calculation
    const handleInput = (e) => {
        let cell = e.target;
        let value = cell.innerText.trim();

        if (!value) return;

        if (typeof value === 'string' && value.startsWith('=')) {
            // Intercept the input if it looks like a formula
            const formula = value;

            try {
                // Calculate and update the cell content
                const result = evaluateFormula(formula, document); 
                cell.innerText = result;
            } catch (e) {
                 console.error("Error handling input:", e);
            }
        } else if (!value.startsWith('=')) {
             // If user inputs plain text/number, we don't override it.
        }
    };

    const cells = document.querySelectorAll('#spreadsheetTable td[contenteditable="true"]');

    cells.forEach(cell => {
        // Use 'input' event to catch changes from typing or pasting
        cell.addEventListener('input', handleInput);
        // Also attach click listener for selection (this handles the initial setup)
        cell.addEventListener('click', selectCellHandler); 
    });

    // --- Color Picker Functionality Setup ---
    const colorPicker = document.getElementById('backgroundColorPicker');
    const applyButton = document.getElementById('applyColorButton');

    if (colorPicker && applyButton) {
        // Listener for the Apply button
        applyButton.addEventListener('click', () => {
            const selectedColor = colorPicker.value;
            applyBackgroundColor(selectedColor);
        });

        // Initialize selection if a cell is clicked via JS interaction (though click listener handles it)
    }


    console.log("Spreadsheet App Initialized: Ready for input.");
}
