```js
function handleColumnClick(e) {
    const header = e.currentTarget;
    const columnLetter = header.getAttribute('data-column-letter');

    // 1. Deseleccionar cualquier columna actual
    document.querySelectorAll('.column-header').forEach(h => h.classList.remove('selected-column'));

    // 2. Seleccionar la nueva columna
    header.classList.add('selected-column');

    // 3. Actualizar el estado de selección y los controles
    window._selectedColumn = columnLetter; // Guardar en window para acceso global
    updateControlButtons(columnLetter);
}

/**
 * Updates the UI controls (buttons and label) based on the selected column.
 * @param {string} letter - The letter of the currently selected column (e.g., 'A').
 */
function updateControlButtons(letter) {
    const isSelected = !!letter;
    document.getElementById('selectedColumnLabel').textContent = `Columna ${letter}`;

    // Habilitar/Deshabilitar botones
    document.getElementById('clearColumnBtn').disabled = !isSelected;
    document.getElementById('colorColumnBtn').disabled = !isSelected;
    document.getElementById('deleteColumnBtn').disabled = !isSelected;
}


/**
 * Clears all content in the selected column.
 */
function clearColumn() {
    const letter = window._selectedColumn;
    if (!letter) return;

    // Selectores para todas las celdas de la columna: desde A2 hasta J20, etc.
    document.querySelectorAll(`[data-cell^="${letter}"][data-cell$="1"], [data-cell^="${letter}"][data-cell$="2"], ..., [data-cell^="${letter}"][data-cell$="20"]`).forEach(cell => {
        // Usaremos un selector más simple para todos los elementos td con data-cell que empiecen por la letra
        const fullSelector = `[data-cell^="${letter}"]`;
        document.querySelectorAll(fullSelector).forEach(cellToClear => {
            cellToClear.innerText = '';
        });
    });

    // Resetear el estilo de fondo después de borrar
    document.querySelectorAll(`[data-cell^="${letter}"]`).forEach(cell => {
        cell.style.backgroundColor = ''; // Esto elimina cualquier color aplicado
    });
}


/**
 * Changes the background color of all cells in the selected column.
 */
function colorColumn() {
    const letter = window._selectedColumn;
    if (!letter) return;

    // Pedir un input de color simple (o usar un valor predeterminado si es demasiado complejo)
    let newColor = prompt("Por favor, introduce el color de fondo en formato hexadecimal o nombre (ej: #ffcc00 o red):");

    if (newColor && newColor.trim() !== '') {
        // Aplicar el estilo a todas las celdas de la columna seleccionada
        document.querySelectorAll(`[data-cell^="${letter}"]`).forEach(cell => {
            cell.style.backgroundColor = newColor;
        });
    } else {
        alert("Operación cancelada o color inválido.");
    }
}

/**
 * Deletes the selected column and updates all necessary DOM attributes (data-cell, row-label).
 */
function deleteColumn() {
    const letterToDelete = window._selectedColumn;
    if (!letterToDelete) return;

    if (!confirm(`¿Estás seguro de que quieres eliminar la columna ${letterToDelete}? ¡Esta acción no se puede deshacer!`)) {
        return;
    }

    // 1. Eliminar el encabezado de la columna (TH)
    const headerToRemove = document.querySelector(`.column-header[data-column-letter="${letterToDelete}"]`);
    if (headerToRemove) {
        headerToRemove.remove();
    }

    // 2. Identificar todas las celdas y el label asociado a esta columna
    let cellsInColumn = Array.from(document.querySelectorAll(`[data-cell^="${letterToDelete}"]`));
    let rowsAffected = new Set(); // Usamos un set para evitar duplicados de filas

    cellsInColumn.forEach(cell => {
        const rowIdMatch = cell.getAttribute('data-cell').match(/(\d+)$/);
        if (rowIdMatch) {
            rowsAffected.add(parseInt(rowIdMatch[1], 10));
        }
    });

    // 3. Recorrer todas las filas afectadas y reindexar los atributos data-cell
    const rowLabels = document.querySelectorAll('.row-label');
    let currentRowIndex = 1; // Empezamos en la fila 1 (índice del DOM)

    for (let i = 0; i < document.querySelectorAll('#spreadsheetTable tbody tr').length; i++) {
        const row = document.querySelectorAll('#spreadsheetTable tbody tr')[i];
        if (!row) continue;

        // Obtener el label de la fila actual (e.g., '1', '2', ...)
        let rowLabelElement = row.querySelector('.row-label');
        let rowIndex = parseInt(rowLabelElement.textContent, 10);


        // Iterar sobre todas las celdas (TD) en esta fila
        const cellsInRow = Array.from(row.querySelectorAll('td[contenteditable="true"]'));

        cellsInRow.forEach((cell, colIndex) => {
            let cellDataCell = cell.getAttribute('data-cell');

            // Si la celda está en la columna a eliminar (esto solo ocurre si el DOM no se ha reconstruido)
            if (cellDataCell && cellDataCell.toUpperCase().startsWith(letterToDelete)) {
                // Esta celda debe ser eliminada del DOM, ya que su contenido ahora pertenece a la derecha.
                cell.remove(); 
                return; // Saltar al siguiente TD en esta fila
            }

            let currentLetter = '';
            // Determinar la letra de la columna actual (esto es complejo porque el índice no siempre coincide con la letra)
            // Buscamos la etiqueta TH anterior para obtener la letra.
            const colHeaderCells = document.querySelectorAll('#spreadsheetTable thead tr .column-header');
            let currentColIndexInDOM = Array.from(colHeaderCells).findIndex(h => h === cell.parentNode.querySelector('.column-header'));

            if (currentColIndexInDOM >= 0) {
                currentLetter = colHeaderCells[currentColIndexInDOM].getAttribute('data-column-letter');
            } else {
                 // Si no podemos determinar la letra, asumimos que el índice del TD es lo más fiable.
                 // Dado que estamos eliminando una columna en medio, esta aproximación es necesaria.
                currentLetter = String.fromCharCode('A'.charCodeAt(0) + colIndex); 
            }


            // Re-indexar los atributos data-cell para la celda actual
            let newCellData;

            if (letterToDelete === 'A') {
                // Si eliminamos A, todas las celdas se mueven a la izquierda y sus letras cambian.
                newCellData = `${String.fromCharCode('A'.charCodeAt(0) + colIndex - 1)}${rowIndex}`;
            } else if (letterToDelete === 'B' && colIndex > 0) {
                 // Si eliminamos B, las celdas de C, D... se mueven a la izquierda y sus letras cambian.
                newCellData = `${String.fromCharCode('A'.charCodeAt(0) + colIndex - 1)}${rowIndex}`;
            } else if (letterToDelete !== 'A' && letterToDelete !== 'B') {
                 // Para todas las demás columnas, el índice de la columna se ajusta.
                newCellData = `${String.fromCharCode('A'.charCodeAt(0) + colIndex - 1)}${rowIndex}`;
            } else {
                // Caso base (esto debería ser manejado por los casos anteriores, pero es un fallback).
                newCellData = cellDataCell;
            }

            // Actualizar el atributo data-cell de la celda sobreviviente
            cell.setAttribute('data-cell', newCellData);
        });
    }


    // 4. Reconstruir manualmente los índices de columna en TODAS las filas (más seguro que depender del DOM)
    const allRows = document.querySelectorAll('#spreadsheetTable tbody tr');

    for (let i = 0; i < allRows.length; i++) {
        const row = allRows[i];
        // Asumiendo que el número de columnas se ha reducido en 1, y los índices deben recalcularse.
        // Este es el punto más frágil del código sin un framework.

        let cellsInRow = Array.from(row.querySelectorAll('td[contenteditable="true"]'));

        // Reajustar data-cell para todas las celdas de la fila
        for (let j = 0; j < cellsInRow.length; j++) {
             const cell = cellsInRow[j];
             const rowIndex = parseInt(rowLabels[i].textContent, 10);

             // La letra de la columna ahora es A + índice de columna sobreviviente (j)
             const newLetterCode = 'A'.charCodeAt(0) + j;
             cell.setAttribute('data-cell', String.fromCharCode(newLetterCode) + rowIndex);
        }
    }


    alert(`Columna ${letterToDelete} eliminada exitosamente. Los índices de todas las celdas han sido corregidos.`);
    // Forzar la actualización de los controles
    window._selectedColumn = null;
    updateControlButtons(null);
}
