### FUNCION: handleColumnClick
```js
/**
 * Handles the click event on a column letter header, selecting the column 
 * and enabling/disabling control buttons accordingly.
 * @param {string} columnLetter The letter of the selected column (e.g., 'A').
 */
function handleColumnClick(columnLetter) {
    const headers = document.querySelectorAll('#spreadsheetTable th');
    const container = document.querySelector('.controls-panel');

    // 1. Deselect previous column and clear active state
    headers.forEach(th => {
        if (th.textContent.trim() !== '') { // Only check letter columns, not the corner cell
            th.classList.remove('selected-column');
        }
    });
    document.getElementById('deleteColumnBtn').disabled = true;
    document.getElementById('clearColumnBtn').disabled = true;

    // 2. Select current column and set state
    let selectedHeader = null;
    headers.forEach(th => {
        if (th.textContent.trim() === columnLetter) {
            selectedHeader = th;
        }
    });

    if (selectedHeader) {
        selectedHeader.classList.add('selected-column');
        document.getElementById('deleteColumnBtn').disabled = false;
        document.getElementById('clearColumnBtn').disabled = false;
        document.getElementById('selectedColumnDisplay').textContent = `Columna ${columnLetter} seleccionada`;
    } else {
         // Should not happen if called correctly, but good practice
         console.error("Invalid column letter:", columnLetter);
    }
}

/**
 * Clears all content in the currently selected column.
 */
function clearSelectedColumn() {
    const selectedHeader = document.querySelector('.selected-column');
    if (!selectedHeader) return;

    const columnName = selectedHeader.textContent.trim();
    const cells = document.querySelectorAll(`[data-cell^="${columnName}"]`);

    cells.forEach(cell => {
        cell.innerText = '';
    });
}

/**
 * Deletes the currently selected column, removing all associated cells and labels.
 */
function deleteSelectedColumn() {
    const selectedHeader = document.querySelector('.selected-column');
    if (!selectedHeader) return;

    const columnName = selectedHeader.textContent.trim();

    // 1. Remove header cell
    selectedHeader.remove();

    // 2. Find and remove all cells belonging to this column (A, B, C...)
    document.querySelectorAll(`[data-cell^="${columnName}"]`).forEach(cell => {
        cell.remove();
    });

    // 3. Remove corresponding row labels for all rows (1 through 20)
    const rowLabels = document.querySelectorAll('.row-label');
    rowLabels.forEach(label => {
        let labelRow = label.closest('tr');
        if (labelRow && labelRow.querySelector(`[data-cell*="${columnName}"]`)) {
             // The structure is: <th class="row-label">R</th> <td data-cell="A...">...</td> ... <th>L</th>
             // We need to find the column index of the letter header and remove the corresponding row label.
        }
    });

    // A simpler approach for removing labels: iterate through all rows (tr) after thead, and remove the Nth th element if it matches the column.
    const tbody = document.querySelector('#spreadsheetTable tbody');
    if (tbody) {
        Array.from(tbody.rows).forEach(row => {
            // The row label is always the first <th> child of the row
            let cellsInRow = Array.from(row.querySelectorAll('th, td'));
            // If we removed the letter header, the corresponding cell in the body needs to be removed too.
            if (cellsInRow.length > 1) {
                // Check if the Nth element is a data-cell matching the column name.
                let targetCell = Array.from(row.querySelectorAll(`[data-cell^="${columnName}"]`))[0];
                 if (targetCell) {
                    targetCell.remove();
                 }
            }

        });
    }


    // Reset selection state and controls display
    document.getElementById('deleteColumnBtn').disabled = true;
    document.getElementById('clearColumnBtn').disabled = true;
    selectedHeader.classList.remove('selected-column');
    document.getElementById('selectedColumnDisplay').textContent = 'Columna seleccionada';

}
