### FUNCION: setupSpreadsheet
```js
/**
 * @function setupSpreadsheet
 * Initializes the spreadsheet functionality, ensuring structural elements 
 * (headers, row labels, and editable cells) are ready for user interaction.
 */
function setupSpreadsheet() {
    // State variable to track the currently selected column letter (e.g., 'A')
    let selectedColumn = null;

    // --- Event Handlers ---

    // 1. Handle Input/Formula Calculation on Cells
    const handleInput = (e) => {
        let cell = e.target;
        let value = cell.innerText.trim();

        if (!value) return;

        if (typeof value === 'string' && value.startsWith('=')) {
            // Intercept the input if it looks like a formula
            const formula = value;

            try {
                // Calculate and update the cell content
                const result = evaluateFormula(formula, document); 
                cell.innerText = result;
            } catch (e) {
                 console.error("Error handling input:", e);
            }
        } else if (!value.startsWith('=')) {
             // If user inputs plain text/number, we don't override it.
        }
    };

    const cells = document.querySelectorAll('#spreadsheetTable td[contenteditable="true"]');
    cells.forEach(cell => {
        cell.addEventListener('input', handleInput);
    });


    // 2. Handle Column Selection on Headers (A, B, C...)
    const columnHeaders = document.querySelectorAll('.col-label');
    columnHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const columnName = this.getAttribute('data-column');

            // Update state and UI selection indicators
            selectedColumn = columnName;
            document.querySelector('#selectColumnButton').disabled = false;
            updateControlButtonsState();
            console.log(`Selected column: ${selectedColumn}`);
        });
    });


    // 3. Handle Column Actions (Buttons)
    document.getElementById('clearColumnContentBtn').addEventListener('click', () => {
        if (!selectedColumn) return;

        const targetCol = document.querySelectorAll(`.data-cell[data-column="${selectedColumn}"]`);
        targetCol.forEach(cell => {
            // Clear content but keep the editable attribute for future use
            cell.innerText = ''; 
        });
    });

    document.getElementById('setBackgroundColorBtn').addEventListener('click', () => {
        if (!selectedColumn) return;

        const targetCol = document.querySelectorAll(`.data-cell[data-column="${selectedColumn}"]`);
        targetCol.forEach(cell => {
            // Apply background color style directly to the element
            cell.style.backgroundColor = '#fff3cd'; // Light yellow warning color
        });
    });

    document.getElementById('deleteColumnBtn').addEventListener('click', () => {
        if (!selectedColumn) return;

        const columnLetters = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
        let columnIndex = -1;
        columnLetters.forEach((letter, index) => {
            if (letter === selectedColumn) {
                columnIndex = index + 2; // +2 accounts for the corner cell and row labels
            }
        });

        if (columnIndex < 1 || columnIndex > 11) return;

        // Remove Header Cell
        const headerCell = document.querySelector(`#spreadsheetTable thead tr th:nth-child(${columnIndex})`);
        headerCell.remove();

        // Remove Body Cells (Iterate through rows and remove the cell at the corresponding index)
        document.querySelectorAll('#spreadsheetTable tbody tr').forEach(row => {
            const cellToRemove = row.querySelector(`td:nth-child(${columnIndex})`);
            if (cellToRemove) {
                cellToRemove.remove();
            }
        });

        // Reset selection state after deletion
        selectedColumn = null;
        updateControlButtonsState(true); // Update buttons and remove visual selection if any
    });


    /**
     * Updates the disabled status of all action buttons based on whether a column is selected.
     * @param {boolean} forceReset If true, resets the selection state regardless of current value.
     */
    const updateControlButtonsState = (forceReset = false) => {
        if (forceReset || !selectedColumn) {
            document.getElementById('clearColumnContentBtn').disabled = true;
            document.getElementById('setBackgroundColorBtn').disabled = true;
            document.getElementById('deleteColumnBtn').disabled = true;
            // Optional: Visually deselect column headers if needed, but current implementation relies on JS state.
        } else {
            document.getElementById('clearColumnContentBtn').disabled = false;
            document.getElementById('setBackgroundColorBtn').disabled = false;
            document.getElementById('deleteColumnBtn').disabled = false;
        }
    };

    // Initial setup and event binding (using the new handlers)
    setupSpreadsheet(); // Call self to ensure initial state is set up correctly
}
