/**
 * Selects a column by clicking its header letter and updates the control panel.
 * @param {string} colLetter The letter of the selected column (e.g., 'A').
 */
function selectColumn(colLetter) {
    // 1. Deselect previous column
    document.querySelectorAll('.column-header').forEach(header => {
        header.classList.remove('selected');
        header.style.backgroundColor = ''; // Reset background color
    });

    // 2. Select current column header and update UI state
    const selectedHeader = document.querySelector(`.column-header[data-col-letter="${colLetter}"]`);
    if (selectedHeader) {
        selectedHeader.classList.add('selected');
    }

    document.getElementById('selectedColLetter').textContent = colLetter;
    document.getElementById('columnControls').classList.remove('hidden');

    // Reset controls to default state when a new column is selected
    document.getElementById('colorPicker').value = '#ffffff';

    // Optional: Set initial background color on the header for visual feedback
    selectedHeader.style.backgroundColor = '#e0f7fa'; 
}
