        for (let i = 0; i < cells.length; i++) {
            if (cells[i].getAttribute('data-cell') && cells[i].getAttribute('data-cell').startsWith(colLetter)) {
                cells[i].remove();
                // Stop after finding the first instance, assuming sequential structure
                break; 
            }
        }
    });
