/**
 * @function setupSpreadsheet
 * Initializes the spreadsheet functionality, ensuring structural elements 
 * (headers, row labels, and editable cells) are ready for user interaction.
 */
function setupSpreadsheet() {
    // Function to handle cell input and automatic formula calculation
    const handleInput = (e) => {
        let cell = e.target;
        let value = cell.innerText.trim();

        if (!value) return;

        if (typeof value === 'string' && value.startsWith('=')) {
            // Intercept the input if it looks like a formula
            const formula = value;

            try {
                // Calculate and update the cell content
                const result = evaluateFormula(formula, document); 
                cell.innerText = result;
            } catch (e) {
                 console.error("Error handling input:", e);
            }
        } else if (!value.startsWith('=')) {
             // If user inputs plain text/number, we don't override it.
        }
    };

    const cells = document.querySelectorAll('#spreadsheetTable td[contenteditable="true"]');

    cells.forEach(cell => {
        // Use 'input' event to catch changes from typing or pasting
        cell.addEventListener('input', handleInput);
    });

    // --- R6: Setup Column Selection and Controls ---
    const columnHeaders = document.querySelectorAll('.column-header');
    columnHeaders.forEach(header => {
        header.addEventListener('click', function() {
            selectColumn(this.getAttribute('data-col-letter'));
        });
    });

    // Setup Event Listeners for Controls Panel
    document.getElementById('applyColorBtn').addEventListener('click', () => {
        const colLetter = document.getElementById('selectedColLetter').textContent;
        const color = document.getElementById('colorPicker').value;
        if (colLetter) changeBackgroundColor(colLetter, color);
    });

    document.getElementById('clearColumnBtn').addEventListener('click', () => {
        const colLetter = document.getElementById('selectedColLetter').textContent;
        if (colLetter && confirm(`¿Está seguro que desea limpiar toda la columna ${colLetter}?`)) {
            clearColumn(colLetter);
        }
    });

    document.getElementById('deleteColumnBtn').addEventListener('click', () => {
        const colLetter = document.getElementById('selectedColLetter').textContent;
        if (colLetter && confirm(`¡ADVERTENCIA! ¿Está seguro que desea BORRAR la columna ${colLetter}? Esta acción es irreversible.`)) {
            deleteColumn(colLetter);
        }
    });


    console.log("Spreadsheet App Initialized: Ready for input.");
}
