function deleteColumn(colLetter) {
    if (!confirm(`¿Está seguro de que desea borrar la columna ${colLetter}? Esta acción es irreversible.`)) return;

    const headers = document.querySelectorAll('#spreadsheetTable thead th');
    let targetHeader = null;
    for (let i = 0; i < headers.length; i++) {
        if (headers[i].innerText.trim().toUpperCase() === colLetter) {
            targetHeader = headers[i];
            break;
        }
    }

    if (!targetHeader) return;

    // 1. Remove the header cell
    targetHeader.remove();

    // 2. Remove all data cells in that column (td elements)
    const rowLabels = document.querySelectorAll('.row-label');
    let columnIndex = -1; // We need to find the index again for td selection
    for(let i=0; i < headers.length; i++) {
        if (headers[i].innerText.trim().toUpperCase() === colLetter) {
            columnIndex = i + 1; // Accounting for the row label column
            break;
        }
    }

    // Iterate over rows and remove the specific td cell
    document.querySelectorAll('#spreadsheetTable tbody tr').forEach(row => {
        const cells = row.querySelectorAll('td');
        if (columnIndex !== -1 && cells[columnIndex - 1]) {
            cells[columnIndex - 1].remove();
        }
    });

    // Re-run setup to update potential listeners/state if needed
    setupSpreadsheet();
    hideColumnContextMenu(); // Hide menu after action
}
