/**
 * Sets up event listeners for row labels, allowing selection and triggering actions.
 */
function setupRowListeners() {
    const rowLabels = document.querySelectorAll('.row-label');
    if (rowLabels.length === 0) return;

    // Function to display/hide controls and set the selected row state
    const selectRow = (e, rowElement) => {
        // Deselect previous row if any
        document.querySelectorAll('.row-label').forEach(el => el.classList.remove('selected'));

        // Select current row
        rowLabels[Array.from(rowLabels).indexOf(e.target)].classList.add('selected');

        // Show controls and store reference to the selected row element (the TR)
        const selectedRow = e.target.closest('tr');
        document.getElementById('row-controls').classList.remove('hidden');
        window._selectedRowElement = selectedRow; // Store globally for action handlers
    };

    // Attach event listener to all row labels
    rowLabels.forEach(label => {
        label.addEventListener('click', (e) => {
            selectRow(e, e.target);
        });
    });
}
