function setupSpreadsheet() {
    // Global state to track the currently selected row element and its number
    let selectedRow = null; 
    const ROW_LABELS = document.querySelectorAll('.row-label');

    /**
     * Selects a specific row by clicking its label, applying visual feedback.
     * @param {HTMLElement} rowLabelElement - The clicked row label element.
     */
    const selectRow = (rowLabelElement) => {
        if (selectedRow) {
            // Deselect previous row
            selectedRow.classList.remove('selected-row');
        }

        // Select the new row
        selectedRow = rowLabelElement;
        selectedRow.classList.add('selected-row');

        const rowNumber = selectedRow.getAttribute('data-row-number');
        const parentRow = selectedRow.closest('tr');

        if (parentRow) {
            // Apply selection class to the entire row for visual feedback
            parentRow.setAttribute('data-is-selected', 'true');
        }

        updateControls(rowNumber);
    };

    /**
     * Updates the control panel buttons and state based on the selected row.
     * @param {string | null} rowNumber - The number of the currently selected row.
     */
    const updateControls = (rowNumber) => {
        if (!rowNumber) {
            // No row selected
            document.getElementById('deleteRowButton').disabled = true;
            return;
        }

        // Enable delete button if a row is selected
        document.getElementById('deleteRowButton').disabled = false;
    };


    /**
     * Clears all content from the currently selected row.
     */
    const clearSelectedRowContents = () => {
        if (!selectedRow) return;

        // Get the entire row element (which is a <tr>)
        const parentRow = selectedRow.closest('tr');
        if (!parentRow) return;

        // Select all data cells within that row and clear their content
        const cells = parentRow.querySelectorAll('td[contenteditable="true"]');
        cells.forEach(cell => {
            cell.innerText = '';
        });
    };

    /**
     * Changes the background color of the entire selected row's cells.
     * @param {string} color - The hex color code.
     */
    const changeBackgroundColor = (color) => {
        if (!selectedRow) return;

        // Get the entire row element
        const parentRow = selectedRow.closest('tr');
        if (!parentRow) return;

        // Apply background color to all cells in that row, including the label cell itself if desired
        parentRow.style.backgroundColor = color;
    };


    /**
     * Deletes the entire selected row from the table structure and updates data attributes/listeners.
     */
    const deleteSelectedRow = () => {
        if (!selectedRow) return;

        // 1. Get the parent row element (<tr>)
        const parentRow = selectedRow.closest('tr');
        if (!parentRow) return;

        // 2. Remove the row from the DOM
        parentRow.remove();

        // 3. Reset state and controls
        selectedRow = null;
        document.querySelectorAll('.row-label').forEach(el => el.classList.remove('selected-row'));
        updateControls(null);
    };


    // --- Event Listeners Setup ---

    // 1. Row Label Click Listener (Selecting the row)
    ROW_LABELS.forEach(header => {
        header.addEventListener('click', function() {
            selectRow(this);
        });
    });

    // 2. Control Panel Listeners
    document.getElementById('applyColorButton').addEventListener('click', () => {
        const color = document.getElementById('colorPicker').value;
        changeBackgroundColor(color);
    });

    document.getElementById('clearRowContentButton').addEventListener('click', clearSelectedRowContents);

    document.getElementById('deleteRowButton').addEventListener('click', deleteSelectedRow);


    // 3. Column Header Click Listener (Existing functionality)
    const colHeaders = document.querySelectorAll('.col-header');
    colHeaders.forEach(header => {
        header.addEventListener('click', function() {
            const colLetter = this.getAttribute('data-column-letter');
            if (colLetter) {
                // Clear column content when header is clicked
                clearColumn(colLetter);
                // Optional: Deselect row if clearing a whole column might be unexpected interaction
                selectedRow = null;
                document.querySelectorAll('.row-label').forEach(el => el.classList.remove('selected-row'));
                updateControls(null);

            }
        });
    });


    // 4. Cell Input Listener (Existing functionality)
    const cells = document.querySelectorAll('#spreadsheetTable td[contenteditable="true"]');
    cells.forEach(cell => {
        cell.addEventListener('input', handleInput);
    });


    console.log("Spreadsheet App Initialized: Ready for input and row manipulation.");
}

// Start the application when the script loads
